var a=35;var i=[{id:`cooking-035-01`,theoryId:35,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Why dice vegetables to similar sizes for one pan?`,ua:`Навіщо нарізати овочі приблизно однаковими кубиками для однієї сковороди?`},explanation:{en:`Similar thickness tends to produce more uniform cooking.`,ua:`Схожа товщина зазвичай забезпечує рівномірніше приготування.`},options:[{id:`a`,text:{en:`To make every piece heavier`,ua:`Щоб кожен шматок став важчим`}},{id:`b`,text:{en:`To make heating and texture more consistent`,ua:`Щоб приготування й текстура були рівномірнішими`}},{id:`c`,text:{en:`To eliminate all vitamin loss`,ua:`Щоб усунути будь-яку втрату вітамінів`}}],answer:{optionIds:[`b`]}},{id:`cooking-035-02`,theoryId:35,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Large cubes of carrot usually soften faster than much smaller cubes under the same conditions.`,ua:`Великі кубики моркви за однакових умов зазвичай м’якшають швидше за значно менші.`},explanation:{en:`Heat takes longer to reach the center of larger pieces.`,ua:`Тепло довше доходить до середини великих шматків.`},answer:{value:!1}},{id:`cooking-035-03`,theoryId:35,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match the cut with its shape.`,ua:`Поєднайте вид нарізання з формою.`},explanation:{en:`The cut shape influences appearance, surface area, and heating.`,ua:`Форма нарізання впливає на вигляд, площу поверхні та нагрівання.`},leftItems:[{id:`l1`,text:{en:`Slice`,ua:`Скибка`}},{id:`l2`,text:{en:`Dice`,ua:`Кубик`}},{id:`l3`,text:{en:`Bias cut`,ua:`Нарізання навскіс`}}],rightItems:[{id:`r3`,text:{en:`Angled cross-section`,ua:`Косий поперечний зріз`}},{id:`r2`,text:{en:`Approximately equal length, width, height`,ua:`Приблизно однакова довжина, ширина й висота`}},{id:`r1`,text:{en:`Thin broad piece`,ua:`Тонкий плаский шматочок`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-035-04`,theoryId:35,type:`sequence`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Arrange stable dice preparation for a long carrot.`,ua:`Розташуйте кроки безпечного нарізання довгої моркви кубиками.`},explanation:{en:`Cubes are produced consistently from strips of even thickness.`,ua:`Рівні смужки дозволяють отримати однакові кубики.`},steps:[{id:`s2`,text:{en:`Slice lengthwise into even slabs and strips`,ua:`Нарізати вздовж рівними пластинами й смужками`}},{id:`s1`,text:{en:`Make manageable stable pieces`,ua:`Розділити на зручні стійкі частини`}},{id:`s3`,text:{en:`Cut across strips to form cubes`,ua:`Нарізати смужки поперек на кубики`}}],answer:{order:[`s1`,`s2`,`s3`]}},{id:`cooking-035-05`,theoryId:35,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A soup has tiny potato cubes and very large potato pieces. What change would help?`,ua:`У супі є дрібні й дуже великі шматочки картоплі. Що допоможе?`},explanation:{en:`Uneven dimensions produce uneven tenderness and appearance.`,ua:`Нерівні розміри спричиняють різну м’якість і вигляд.`},options:[{id:`a`,text:{en:`Use more uniform pieces so they finish together`,ua:`Нарізати рівномірніше, щоб картопля готувалася одночасно`}},{id:`b`,text:{en:`Add more pepper`,ua:`Додати більше перцю`}},{id:`c`,text:{en:`Always boil twice as long`,ua:`Завжди варити вдвічі довше`}}],answer:{optionIds:[`a`]}}];var n={theoryId:35,exercises:i};export{n as default,i as exercises,a as theoryId};